{"content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ARTIFACT: Museum Night — 18 October 2026, The Old Gallery, Warsaw</title>
<meta name="description" content="ARTIFACT: Museum Night — a cinematic after-hours museum event with exhibitions, performances, talks, and guided tours. 18 October 2026, 19:00–02:00, The Old Gallery, Warsaw.">
<meta property="og:title" content="ARTIFACT: Museum Night">
<meta property="og:description" content="A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours. 18 October 2026, 19:00–02:00, The Old Gallery, Warsaw.">
<meta property="og:image" content="https://source.unsplash.com/featured/2400x1400?museum,night">
<meta property="og:type" content="website">
<link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' fill='%23070506'/><path d='M8 22 L16 8 L24 22 Z' fill='none' stroke='%23d6ad60' stroke-width='1.5'/><circle cx='16' cy='12' r='2' fill='%23f3d79b'/></svg>">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#070506;
  --velvet:#1a0710;
  --burgundy:#3a0f1d;
  --navy:#07111f;
  --gold:#d6ad60;
  --softgold:#f3d79b;
  --ivory:#f8efe2;
  --muted:#b9a999;
  --panel:rgba(255,244,220,0.06);
  --border:rgba(214,173,96,0.28);
  --serif:Georgia,'Times New Roman',serif;
  --sans:Inter,system-ui,'Segoe UI',sans-serif;
}
html{scroll-behavior:smooth}
body{
  background:var(--bg);
  color:var(--ivory);
  font-family:var(--sans);
  line-height:1.6;
  overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
body::before{
  content:"";
  position:fixed;
  inset:0;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.05'/%3E%3C/svg%3E");
  pointer-events:none;
  z-index:9999;
  opacity:0.5;
}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none;color:inherit}
:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
.wrap{max-width:1240px;margin:0 auto;padding:0 24px}
.gold-line{height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);opacity:0.4}

/* NAV */
.nav{
  position:sticky;top:0;z-index:100;
  background:rgba(7,5,6,0.82);
  backdrop-filter:blur(14px);
  -webkit-backdrop-filter:blur(14px);
  border-bottom:1px solid var(--border);
}
.nav-inner{display:flex;align-items:center;justify-content:space-between;height:72px}
.brand{font-family:var(--serif);font-size:20px;letter-spacing:0.22em;font-weight:700;color:var(--softgold)}
.brand span{color:var(--gold)}
.nav-links{display:flex;gap:32px;align-items:center}
.nav-links a{
  font-size:13px;letter-spacing:0.14em;text-transform:uppercase;
  color:var(--muted);transition:color .25s;
  position:relative;padding:4px 0;
}
.nav-links a::after{
  content:"";position:absolute;left:0;bottom:0;height:1px;width:0;
  background:var(--gold);transition:width .3s;
}
.nav-links a:hover{color:var(--ivory)}
.nav-links a:hover::after,.nav-links a.active::after{width:100%}
.nav-links a.active{color:var(--softgold)}
.cta-btn{
  font-size:12px;letter-spacing:0.16em;text-transform:uppercase;
  padding:12px 22px;border:1px solid var(--gold);color:var(--softgold);
  background:transparent;transition:all .25s;
}
.cta-btn:hover{background:var(--gold);color:var(--bg)}
.menu-btn{display:none;width:40px;height:40px;flex-direction:column;justify-content:center;gap:5px}
.menu-btn span{display:block;width:22px;height:1.5px;background:var(--softgold);transition:transform .3s,opacity .3s}
.mobile-menu{
  position:fixed;top:72px;left:0;right:0;bottom:0;
  background:rgba(7,5,6,0.98);backdrop-filter:blur(14px);
  transform:translateX(100%);transition:transform .35s;z-index:90;
  padding:32px 24px;display:flex;flex-direction:column;gap:28px;
}
.mobile-menu.open{transform:translateX(0)}
.mobile-menu a{font-family:var(--serif);font-size:28px;color:var(--ivory);letter-spacing:0.04em}
.mobile-menu a:hover{color:var(--gold)}
.mobile-cta{margin-top:auto;padding-top:24px;border-top:1px solid var(--border)}

/* HERO */
.hero{
  position:relative;min-height:100vh;display:flex;align-items:center;
  overflow:hidden;background:#000;
}
.hero-img{
  position:absolute;inset:0;width:100%;height:100%;
  object-fit:cover;opacity:0.55;
  filter:blur(0.4px) saturate(1.1);
}
.hero-overlay{
  position:absolute;inset:0;
  background:
    radial-gradient(ellipse 80% 50% at 50% 40%,rgba(214,173,96,0.16),transparent 60%),
    linear-gradient(180deg,rgba(7,5,6,0.4),rgba(7,5,6,0.85) 70%,#000);
}
.hero-spot{
  position:absolute;inset:0;
  background:radial-gradient(circle 30% 20% at 70% 30%,rgba(243,215,155,0.08),transparent 60%);
}
.hero-content{
  position:relative;z-index:2;width:100%;
}
.hero-eyebrow{
  font-size:11px;letter-spacing:0.32em;text-transform:uppercase;
  color:var(--gold);margin-bottom:24px;display:flex;align-items:center;gap:12px;
}
.hero-eyebrow::before{content:"";width:48px;height:1px;background:var(--gold)}
.hero h1{
  font-family:var(--serif);
  font-size:clamp(44px,8vw,112px);
  font-weight:400;line-height:1.02;letter-spacing:-0.01em;
  color:var(--ivory);max-width:18ch;margin-bottom:28px;
}
.hero h1 em{font-style:italic;color:var(--gold)}
.hero-event{
  font-family:var(--serif);font-size:clamp(20px,3vw,34px);
  letter-spacing:0.06em;color:var(--softgold);
  margin-bottom:36px;padding-bottom:24px;border-bottom:1px solid var(--border);
}
.hero-meta{
  display:flex;flex-wrap:wrap;gap:16px;margin-bottom:40px;
}
.meta-badge{
  display:flex;align-items:center;gap:12px;
  padding:10px 16px;border:1px solid var(--border);
  background:var(--panel);font-size:13px;letter-spacing:0.04em;
}
.meta-badge .dot{width:6px;height:6px;border-radius:50%;background:var(--gold)}
.meta-badge strong{display:block;font-family:var(--serif);font-size:15px;color:var(--ivory);letter-spacing:0.02em}
.meta-badge span{color:var(--muted);font-size:12px;letter-spacing:0.08em;text-transform:uppercase}
.hero-cta{display:flex;gap:16px;flex-wrap:wrap}
.btn-primary{
  font-size:13px;letter-spacing:0.16em;text-transform:uppercase;
  padding:16px 32px;background:var(--gold);color:var(--bg);
  font-weight:600;transition:all .25s;position:relative;overflow:hidden;
}
.btn-primary:hover{background:var(--softgold);transform:translateY(-2px);box-shadow:0 12px 30px rgba(214,173,96,0.25)}
.btn-secondary{
  font-size:13px;letter-spacing:0.16em;text-transform:uppercase;
  padding:16px 32px;border:1px solid var(--gold);color:var(--softgold);
  transition:all .25s;
}
.btn-secondary:hover{background:var(--gold);color:var(--bg)}
.hero-scroll{
  position:absolute;bottom:32px;left:50%;transform:translateX(-50%);
  z-index:2;display:flex;flex-direction:column;align-items:center;gap:8px;
  color:var(--muted);font-size:10px;letter-spacing:0.2em;text-transform:uppercase;
}
.hero-scroll .line{width:1px;height:40px;background:linear-gradient(180deg,var(--gold),transparent);animation:scrollPulse 2.4s ease-in-out infinite}
@keyframes scrollPulse{0%,100%{opacity:0.3}50%{opacity:1}}

/* SECTION HEADER */
.section{padding:100px 0;position:relative}
.section-header{margin-bottom:64px;max-width:720px}
.section-label{
  font-size:11px;letter-spacing:0.32em;text-transform:uppercase;
  color:var(--gold);margin-bottom:16px;display:flex;align-items:center;gap:12px;
}
.section-label::before{content:"";width:32px;height:1px;background:var(--gold)}
.section h2{
  font-family:var(--serif);font-size:clamp(32px,5vw,52px);
  font-weight:400;line-height:1.1;color:var(--ivory);margin-bottom:20px;
}
.section h2 em{font-style:italic;color:var(--gold)}
.section-lede{
  font-size:16px;color:var(--muted);max-width:56ch;line-height:1.7;
}

/* CONCEPT */
.concept-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
.concept-text p{font-size:17px;color:var(--muted);line-height:1.8;margin-bottom:18px}
.concept-text p:first-child{font-family:var(--serif);font-size:21px;color:var(--ivory);line-height:1.5}
.concept-text .pull{
  font-family:var(--serif);font-size:28px;color:var(--gold);
  line-height:1.3;margin:28px 0;padding:24px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);
}
.feature-cards{display:grid;gap:20px}
.feature-card{
  background:var(--panel);border:1px solid var(--border);
  padding:32px;transition:all .35s;position:relative;overflow:hidden;
}
.feature-card::before{
  content:"";position:absolute;top:0;left:0;width:3px;height:0;
  background:var(--gold);transition:height .4s;
}
.feature-card:hover{transform:translateY(-4px);border-color:var(--gold);box-shadow:0 20px 40px rgba(0,0,0,0.4)}
.feature-card:hover::before{height:100%}
.feature-card .num{
  font-family:var(--serif);font-size:14px;color:var(--gold);
  letter-spacing:0.1em;margin-bottom:14px;
}
.feature-card h3{
  font-family:var(--serif);font-size:22px;color:var(--ivory);
  margin-bottom:10px;font-weight:400;
}
.feature-card p{font-size:14px;color:var(--muted);line-height:1.6}
.feature-card .icon{
  width:44px;height:44px;border:1px solid var(--border);
  display:flex;align-items:center;justify-content:center;
  margin-bottom:18px;color:var(--gold);
}

/* TIMELINE */
.timeline{position:relative;padding-left:48px}
.timeline::before{
  content:"";position:absolute;left:18px;top:8px;bottom:8px;width:1px;
  background:linear-gradient(180deg,var(--gold),var(--border),var(--gold));
}
.tl-item{
  position:relative;padding:0 0 48px 32px;
  opacity:0;transform:translateY(24px);
  transition:opacity .7s,transform .7s;
}
.tl-item.visible{opacity:1;transform:none}
.tl-item:last-child{padding-bottom:0}
.tl-dot{
  position:absolute;left:-41px;top:6px;width:14px;height:14px;
  border-radius:50%;border:1px solid var(--gold);background:var(--bg);
  display:flex;align-items:center;justify-content:center;
}
.tl-dot::after{content:"";width:5px;height:5px;border-radius:50%;background:var(--gold)}
.tl-time{
  font-size:12px;letter-spacing:0.18em;text-transform:uppercase;
  color:var(--gold);margin-bottom:8px;font-weight:600;
}
.tl-title{
  font-family:var(--serif);font-size:22px;color:var(--ivory);
  margin-bottom:8px;font-weight:400;
}
.tl-desc{font-size:14px;color:var(--muted);margin-bottom:10px;max-width:48ch}
.tl-loc{
  display:inline-flex;align-items:center;gap:8px;
  font-size:11px;letter-spacing:0.14em;text-transform:uppercase;
  color:var(--muted);padding:4px 10px;border:1px solid var(--border);
  background:var(--panel);
}
.tl-loc::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--gold)}

/* ARTISTS */
.artists-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.artist-card{
  background:var(--panel);border:1px solid var(--border);
  overflow:hidden;transition:all .35s;cursor:pointer;
}
.artist-card:hover{transform:translateY(-6px);border-color:var(--gold);box-shadow:0 24px 40px rgba(0,0,0,0.5)}
.artist-img{
  width:100%;aspect-ratio:4/3;object-fit:cover;
  display:block;transition:transform .5s;
  background:var(--velvet);
}
.artist-card:hover .artist-img{transform:scale(1.04)}
.artist-body{padding:20px}
.artist-name{
  font-family:var(--serif);font-size:18px;color:var(--ivory);
  margin-bottom:4px;font-weight:400;
}
.artist-role{
  font-size:11px;letter-spacing:0.16em;text-transform:uppercase;
  color:var(--gold);margin-bottom:12px;
}
.artist-tease{font-size:13px;color:var(--muted);line-height:1.5;margin-bottom:14px}
.artist-link{
  font-size:11px;letter-spacing:0.16em;text-transform:uppercase;
  color:var(--softgold);border-bottom:1px solid var(--gold);
  padding-bottom:2px;transition:color .25s;
}
.artist-card:hover .artist-link{color:var(--ivory)}

/* MODAL */
.modal-backdrop{
  position:fixed;inset:0;background:rgba(7,5,6,0.85);
  backdrop-filter:blur(8px);z-index:200;
  display:flex;align-items:center;justify-content:center;
  padding:24px;opacity:0;pointer-events:none;
  transition:opacity .3s;
}
.modal-backdrop.open{opacity:1;pointer-events:auto}
.modal{
  background:linear-gradient(180deg,var(--velvet),var(--bg));
  border:1px solid var(--border);max-width:560px;width:100%;
  max-height:90vh;overflow-y:auto;padding:40px;
  transform:translateY(20px) scale(0.97);
  transition:transform .35s;
}
.modal-backdrop.open .modal{transform:none}
.modal-close{
  position:absolute;top:16px;right:16px;width:36px;height:36px;
  border:1px solid var(--border);color:var(--muted);
  display:flex;align-items:center;justify-content:center;
  transition:all .25s;font-size:18px;line-height:1;
}
.modal-close:hover{color:var(--gold);border-color:var(--gold)}
.modal-img{
  width:100%;aspect-ratio:16/9;object-fit:cover;
  border:1px solid var(--border);margin-bottom:24px;background:var(--velvet);
}
.modal h3{
  font-family:var(--serif);font-size:28px;color:var(--ivory);
  margin-bottom:6px;font-weight:400;
}
.modal .role{
  font-size:11px;letter-spacing:0.16em;text-transform:uppercase;
  color:var(--gold);margin-bottom:20px;
}
.modal .session{
  display:inline-flex;align-items:center;gap:8px;
  font-size:12px;letter-spacing:0.1em;color:var(--softgold);
  padding:6px 12px;border:1px solid var(--border);background:var(--panel);
  margin-bottom:20px;
}
.modal .session::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--gold)}
.modal p{font-size:15px;color:var(--muted);line-height:1.7}

/* VENUE */
.venue-grid{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:start}
.venue-info h3{
  font-family:var(--serif);font-size:24px;color:var(--ivory);
  margin-bottom:8px;font-weight:400;
}
.venue-info .address{
  font-size:14px;color:var(--gold);margin-bottom:24px;letter-spacing:0.04em;
}
.venue-info .info-block{margin-bottom:24px}
.venue-info .info-block h4{
  font-size:11px;letter-spacing:0.2em;text-transform:uppercase;
  color:var(--gold);margin-bottom:8px;font-weight:600;
}
.venue-info .info-block p{font-size:14px;color:var(--muted);line-height:1.6}
.venue-map{
  background:var(--panel);border:1px solid var(--border);
  padding:24px;aspect-ratio:1/0.9;
}
.venue-map svg{width:100%;height:100%;display:block}

/* TICKETS */
.tickets-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:stretch}
.ticket-card{
  background:var(--panel);border:1px solid var(--border);
  padding:36px 28px;display:flex;flex-direction:column;
  transition:all .35s;position:relative;
}
.ticket-card:hover{transform:translateY(-6px);border-color:var(--gold)}
.ticket-card.featured{
  border-color:var(--gold);background:linear-gradient(180deg,rgba(214,173,96,0.08),var(--panel));
  box-shadow:0 0 0 1px var(--gold),0 20px 40px rgba(214,173,96,0.12);
}
.ticket-card.featured::before{
  content:"";position:absolute;top:-1px;left:50%;transform:translateX(-50%);
  width:60px;height:2px;background:var(--gold);
}
.recommended-badge{
  position:absolute;top:-12px;right:20px;
  background:var(--gold);color:var(--bg);
  font-size:10px;letter-spacing:0.16em;text-transform:uppercase;
  padding:6px 12px;font-weight:600;
}
.tier-name{
  font-family:var(--serif);font-size:24px;color:var(--ivory);
  margin-bottom:6px;font-weight:400;
}
.tier-price{
  font-family:var(--serif);font-size:42px;color:var(--gold);
  margin-bottom:6px;font-weight:400;letter-spacing:-0.02em;
}
.tier-price small{font-size:14px;color:var(--muted);font-family:var(--sans);letter-spacing:0.04em;margin-left:4px}
.tier-desc{font-size:13px;color:var(--muted);margin-bottom:24px;letter-spacing:0.04em}
.tier-features{list-style:none;margin-bottom:28px}
.tier-features li{
  font-size:13px;color:var(--muted);padding:8px 0;
  border-top:1px solid var(--border);display:flex;gap:10px;align-items:flex-start;
}
.tier-features li::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--gold);margin-top:8px;flex-shrink:0}
.tier-select{
  margin-top:auto;padding:13px 20px;
  font-size:12px;letter-spacing:0.14em;text-transform:uppercase;
  background:var(--gold);color:var(--bg);font-weight:600;
  transition:all .25s;width:100%;
}
.ticket-card.featured .tier-select{background:var(--softgold)}
.tier-select:hover{filter:brightness(1.08);transform:translateY(-2px)}

/* CHECKOUT MODAL */
.checkout-modal .modal{max-width:480px}
.checkout-modal .modal-img{display:none}
.field{margin-bottom:18px}
.field label{
  display:block;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;
  color:var(--muted);margin-bottom:8px;
}
.field input,.field select{
  width:100%;padding:13px 14px;
  background:var(--bg);border:1px solid var(--border);
  color:var(--ivory);font-family:var(--sans);font-size:14px;
  transition:border-color .25s;
}
.field input:focus,.field select:focus{outline:none;border-color:var(--gold)}
.field input.error{border-color:#c05a5a}
.error-msg{font-size:12px;color:#e08080;margin-top:6px;display:none}
.error-msg.show{display:block}
.check-total{
  display:flex;justify-content:space-between;align-items:center;
  padding:16px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);
  margin-bottom:18px;
}
.check-total .label{font-size:13px;color:var(--muted);letter-spacing:0.06em}
.check-total .price{font-family:var(--serif);font-size:28px;color:var(--gold)}
.terms{
  display:flex;gap:10px;align-items:flex-start;font-size:12px;color:var(--muted);
  margin-bottom:20px;line-height:1.5;
}
.terms input{accent-color:var(--gold);width:16px;height:16px;margin-top:2px;flex-shrink:0}
.checkout-btn{
  width:100%;padding:16px;
  font-size:13px;letter-spacing:0.16em;text-transform:uppercase;
  background:var(--gold);color:var(--bg);font-weight:600;
  transition:all .25s;
}
.checkout-btn:hover{background:var(--softgold);transform:translateY(-1px)}
.checkout-btn:disabled{opacity:0.4;cursor:not-allowed;transform:none}
.success-msg{
  text-align:center;padding:20px 0;color:var(--softgold);
  display:none;
}
.success-msg.show{display:block}
.success-msg .check{font-family:var(--serif);font-size:36px;color:var(--gold);margin-bottom:12px}
.success-msg p{font-size:14px;color:var(--muted)}

/* FAQ */
.faq-list{max-width:760px}
.faq-item{
  border-bottom:1px solid var(--border);
  overflow:hidden;
}
.faq-q{
  width:100%;text-align:left;display:flex;justify-content:space-between;align-items:center;
  padding:24px 0;font-family:var(--serif);font-size:20px;color:var(--ivory);
  transition:color .25s;
}
.faq-item:hover .faq-q{color:var(--gold)}
.faq-q .icon{
  width:28px;height:28px;border:1px solid var(--border);
  display:flex;align-items:center;justify-content:center;
  transition:transform .35s,color .25s;font-size:18px;color:var(--gold);
  flex-shrink:0;
}
.faq-item.open .faq-q .icon{transform:rotate(45deg);color:var(--softgold);border-color:var(--gold)}
.faq-a{
  max-height:0;overflow:hidden;transition:max-height .4s;
}
.faq-a-inner{
  padding:0 0 24px;font-size:14px;color:var(--muted);line-height:1.7;max-width:64ch;
}

/* NEWSLETTER */
.newsletter{
  background:linear-gradient(135deg,var(--velvet),var(--navy));
  border-top:1px solid var(--border);border-bottom:1px solid var(--border);
  padding:80px 0;text-align:center;
}
.newsletter h2{
  font-family:var(--serif);font-size:clamp(28px,4vw,42px);
  font-weight:400;color:var(--ivory);margin-bottom:12px;
}
.newsletter p{color:var(--muted);margin-bottom:32px;max-width:48ch;margin-left:auto;margin-right:auto}
.news-form{display:flex;gap:12px;max-width:480px;margin:0 auto;flex-wrap:wrap;justify-content:center}
.news-form input{
  flex:1;min-width:220px;padding:14px 16px;
  background:var(--bg);border:1px solid var(--border);
  color:var(--ivory);font-family:var(--sans);font-size:14px;
}
.news-form input:focus{outline:none;border-color:var(--gold)}
.news-form button{
  padding:14px 28px;font-size:12px;letter-spacing:0.16em;text-transform:uppercase;
  background:var(--gold);color:var(--bg);font-weight:600;transition:all .25s;
}
.news-form button:hover{background:var(--softgold)}

/* FOOTER */
.footer{padding:64px 0 32px;border-top:1px solid var(--border)}
.footer-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;margin-bottom:40px}
.footer-brand{font-family:var(--serif);font-size:22px;color:var(--softgold);letter-spacing:0.06em;margin-bottom:12px}
.footer-brand span{color:var(--gold)}
.footer-note{font-size:12px;color:var(--muted);line-height:1.6;max-width:32ch}
.footer-links{display:flex;flex-direction:column;gap:10px}
.footer-links a{font-size:13px;color:var(--muted);transition:color .25s;letter-spacing:0.04em}
.footer-links a:hover{color:var(--gold)}
.footer-bottom{
  display:flex;justify-content:space-between;align-items:center;
  padding-top:24px;border-top:1px solid var(--border);
  font-size:11px;color:var(--muted);letter-spacing:0.08em;
  flex-wrap:wrap;gap:12px;
}
.footer-credits{color:var(--gold);font-family:var(--serif);font-size:13px}

/* TOAST */
.toast-container{
  position:fixed;bottom:24px;right:24px;z-index:300;
  display:flex;flex-direction:column;gap:12px;align-items:flex-end;
}
.toast{
  background:var(--velvet);border:1px solid var(--gold);
  padding:14px 20px;font-size:13px;color:var(--ivory);
  box-shadow:0 12px 30px rgba(0,0,0,0.5);
  transform:translateX(120%);opacity:0;
  transition:transform .4s,opacity .4s;
  max-width:340px;
}
.toast.show{transform:translateX(0);opacity:1}
.toast.success{border-color:var(--gold)}
.toast.error{border-color:#c05a5a}
.toast .toast-title{font-weight:600;color:var(--softgold);margin-bottom:4px}
.toast .toast-body{color:var(--muted)}

/* REVEAL */
.reveal{opacity:0;transform:translateY(24px);transition:opacity .8s ease,transform .8s ease}
.reveal.visible{opacity:1;transform:none}

/* RESPONSIVE */
@media(max-width:900px){
  .nav-links{display:none}
