  var faqs = [
    {q:'Is payment processed on this page?',a:'No. This is a demo landing page. Selecting a ticket tier opens a reservation mock — no payment is processed and no real ticket is issued. The “Confirm reservation” button records a mock reservation and shows a success message.'},
