  ];

  /* ---------- BUILD ARTISTS ---------- */
  var grid = document.getElementById('artistsGrid');
  artists.forEach(function(a){
    var card = document.createElement('div');
    card.className = 'artist-card';
    card.setAttribute('role','button');
    card.setAttribute('tabindex','0');
    card.setAttribute('aria-label','View details for '+a.name);
    card.innerHTML =
      '<img class="artist-img" src="'+a.img+'" alt="" loading="lazy">'+
      '<div class="artist-body">'+
        '<div class="artist-name">'+a.name+'</div>'+
        '<div class="artist-role">'+a.role+'</div>'+
        '<div class="artist-tease">'+a.teaser+'</div>'+
        '<div class="artist-link">View details →</div>'+
      '</div>';
    card.addEventListener('click',function(){ openArtist(a); });
    card.addEventListener('keydown',function(e){
      if(e.key==='Enter'||e.key===' '){ e.preventDefault(); openArtist(a); }
    });
    grid.appendChild(card);
  });

  /* ---------- BUILD FAQ ---------- */
  var faqList = document.getElementById('faqList');
  faqs.forEach(function(f){
    var item = document.createElement('div');
    item.className = 'faq-item';
    item.innerHTML =
      '<button class="faq-q" aria-expanded="false">'+
        '<span>'+f.q+'</span>'+
        '<span class="icon" aria-hidden="true">+</span>'+
      '</button>'+
      '<div class="faq-a"><div class="faq-a-inner">'+f.a+'</div></div>';
