  }
  function closeArtist(){
    artistModal.classList.remove('open');
    document.body.style.overflow = '';
  }
  artistClose.addEventListener('click',closeArtist);
  artistModal.addEventListener('click',function(e){
    if(e.target===artistModal) closeArtist();
  });
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape' && artistModal.classList.contains('open')) closeArtist();
  });

  /* ---------- TICKET MODAL ---------- */
  var checkoutModal = document.getElementById('checkoutModal');
  var checkoutClose = document.getElementById('checkoutClose');
  var checkoutTierLabel = document.getElementById('checkoutTierLabel');
  var checkoutTotal = document.getElementById('checkoutTotal');
  var checkoutConfirm = document.getElementById('checkoutConfirm');
  var successMsg = document.getElementById('successMsg');
  var successText = document.getElementById('successText');
  var attendeeName = document.getElementById('attendeeName');
  var attendeeEmail = document.getElementById('attendeeEmail');
  var ticketCount = document.getElementById('ticketCount');
  var termsCheck = document.getElementById('termsCheck');
  var nameError = document.getElementById('nameError');
  var emailError = document.getElementById('emailError');
  var termsError = document.getElementById('termsError');

  var selectedTier = null;
  var selectedPrice = 0;

  function openCheckout(tier,price){
    selectedTier = tier;
    selectedPrice = price;
    checkoutTierLabel.textContent = tier + ' · €' + price + ' per ticket';
    checkoutTotal.textContent = '€' + price;
    checkoutModal.classList.add('open');
    document.body.style.overflow = 'hidden';
    successMsg.classList.remove('show');
    checkoutConfirm.style.display = '';
    attendeeName.value = '';
    attendeeEmail.value = '';
    ticketCount.value = '1';
    termsCheck.checked = false;
    attendeeName.classList.remove('error');
    attendeeEmail.classList.remove('error');
    nameError.classList.remove('show');
    emailError.classList.remove('show');
    termsError.classList.remove('show');
    setTimeout(function(){ attendeeName.focus(); },50);
