    successText.textContent = attendeeName.value.trim() + ', your reservation for ' + ticketCount.value + ' ticket' + (ticketCount.value>1?'s':'') + ' of the ' + selectedTier + ' (€' + total + ') has been recorded. No payment was processed on this page.';
